#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class PrisonEatingSetup {
static PrisonEatingSetup(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/PrisonEating"))return;var action=File.ReadAllText("Temp/PrisonEating").Trim();File.Delete("Temp/PrisonEating");try{if(action=="inspect")Inspect();else if(action=="rig")Rig();else Build();}catch(Exception e){File.WriteAllText("Logs/Prison-eating.txt",e.ToString());}}
static void Rig(){var m=Object.FindFirstObjectByType<PrisonKeysMission>();EditorSceneManager.SaveScene(m.gameObject.scene,"Logs/Prison-before-eating-rig.unity",true);var src=m.diners[0].GetComponentInChildren<SkinnedMeshRenderer>(true);var dst=m.warden.GetComponentInChildren<SkinnedMeshRenderer>(true);var transforms=m.warden.GetComponentsInChildren<Transform>(true);dst.sharedMesh=src.sharedMesh;dst.sharedMaterials=src.sharedMaterials;dst.bones=src.bones.Select(b=>b==m.diners[0].transform?m.warden.transform:transforms.First(t=>t.name==b.name)).ToArray();dst.localBounds=src.localBounds;
var type=typeof(PrisonWardrobeSetup);var flags=System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic;type.GetField("uniform",flags).SetValue(null,AssetDatabase.LoadAssetAtPath<Material>("Assets/DeliveryPrisonChapter/OfficeSearch/간수장 상아색 제복.mat"));type.GetField("shoes",flags).SetValue(null,AssetDatabase.LoadAssetAtPath<Material>("Assets/DeliveryPrisonChapter/OfficeSearch/간수장 구두.mat"));type.GetMethod("Dress",flags).Invoke(null,new object[]{m.warden.transform,"YeomEatingUniform"});EditorSceneManager.MarkSceneDirty(m.gameObject.scene);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(m.gameObject.scene);File.WriteAllText("Logs/Prison-eating-rig.txt","PASS warden uses verified guard bind poses and retained cream costume");}
static void Inspect(){var m=Object.FindFirstObjectByType<PrisonKeysMission>();var b=new System.Text.StringBuilder();foreach(var guard in m.diners.Concat(new[]{m.warden})){b.AppendLine("ACTOR "+guard.name);foreach(var r in guard.GetComponentsInChildren<SkinnedMeshRenderer>(true))b.AppendLine(r.name+" enabled="+r.enabled+" mesh="+AssetDatabase.GetAssetPath(r.sharedMesh)+" bones="+string.Join(",",r.bones.Select(x=>x.name)));foreach(var c in guard.GetComponentsInChildren<MonoBehaviour>(true))b.AppendLine(c.GetType().Name+" "+c.enabled);}File.WriteAllText("Logs/Eating-rigs.txt",b.ToString());}
static void Build(){var m=Object.FindFirstObjectByType<PrisonKeysMission>();var scene=m.gameObject.scene;if(scene.name!="PrisonChapter")throw new Exception("감옥 씬만 수정");EditorSceneManager.SaveScene(scene,"Logs/Prison-before-eating-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);
const string folder="Assets/DeliveryPrisonChapter/Eating";Directory.CreateDirectory(folder);AssetDatabase.Refresh();
Material Mat(string n,Color c){var mat=AssetDatabase.LoadAssetAtPath<Material>(folder+"/"+n+".mat");if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=c};AssetDatabase.CreateAsset(mat,folder+"/"+n+".mat");}return mat;}
var cheese=Mat("구운 치즈",new Color(.95f,.65f,.23f));var crust=Mat("구운 도우",new Color(.58f,.32f,.12f));var pepper=Mat("페페로니",new Color(.5f,.07f,.035f));
var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(folder+"/피자 조각.asset");if(!mesh){mesh=new Mesh();mesh.vertices=new[]{new Vector3(-.12f,0,-.08f),new Vector3(.12f,0,-.08f),new Vector3(0,0,.20f),new Vector3(-.12f,.025f,-.08f),new Vector3(.12f,.025f,-.08f),new Vector3(0,.025f,.20f)};mesh.subMeshCount=2;mesh.SetTriangles(new[]{3,5,4},0);mesh.SetTriangles(new[]{0,1,2,0,3,4,0,4,1,1,4,5,1,5,2,2,5,3,2,3,0},1);mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,folder+"/피자 조각.asset");}
foreach(var guard in m.diners.Concat(new[]{m.warden})){var e=guard.GetComponent<PrisonPizzaEating>()??guard.gameObject.AddComponent<PrisonPizzaEating>();if(e.slice)continue;var g=new GameObject(guard.name+" 먹는 피자 조각",typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(m.transform,false);g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<Renderer>().sharedMaterials=new[]{cheese,crust};for(int i=0;i<3;i++){var p=GameObject.CreatePrimitive(PrimitiveType.Cylinder);p.name="페페로니";p.transform.SetParent(g.transform,false);p.transform.localPosition=new Vector3(i==0?-.045f:i==1?.045f:0,.029f,i==2?.09f:-.025f);p.transform.localScale=new Vector3(.055f,.004f,.055f);p.GetComponent<Renderer>().sharedMaterial=pepper;Object.DestroyImmediate(p.GetComponent<Collider>());}e.slice=g.transform;g.SetActive(false);}
EditorSceneManager.MarkSceneDirty(scene);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);File.WriteAllText("Logs/Prison-eating.txt","PASS saved eating performance and pizza slices for 4 guards");}
}}
#endif
